import ballerina/io;

public function main() {
    anydata[] a = [1, 2];
    a.push(a);
    io:println(a.toBalString()); // @output [1,2,...[0]]
    io:println(a.toString()); // @output [1,2,...]

    map<anydata> m = {x: 1};
    m["self"] = m;
    io:println(m.toBalString()); // @output {"x":1,"self":...[0]}
    io:println(m.toString()); // @output {"x":1,"self":...}

    anydata[] b = [1];
    anydata[] c = [2, b];
    b.push(c);
    io:println(b.toBalString()); // @output [1,[2,...[0]]]
    io:println(b.toString()); // @output [1,[2,...]]

    anydata[] inner = [1];
    inner.push(inner);
    anydata[] top = [0, inner];
    io:println(top.toBalString()); // @output [0,[1,...[1]]]
    io:println(top.toString()); // @output [0,[1,...]]
}
